# Sort by length (longest first) to prevent partial matches
PHRASES.sort(key=lambda x: len(x[0]), reverse=True)


def translate_text(text):
    """Apply phrase-level translation to a text block."""
    for eng, esp in PHRASES:
        if eng in text:
            text = text.replace(eng, esp)
    return text


def process_latex_file(input_path, output_path):
    """Process a LaTeX file, translating natural language text."""
    
    with open(input_path, 'r', encoding='utf-8') as f:
        content = f.read()
    
    # Apply all phrase replacements globally
    for eng, esp in PHRASES:
        if eng in content:
            content = content.replace(eng, esp)
    
    # Fix specific LaTeX-related patterns that may have been broken
    content = content.replace('alpha-LMS', 'α-LMS')
    content = content.replace('mu-LMS', 'μ-LMS')
    
    # Fix "pm 1" to "$\\pm 1$" - only in text mode
    content = content.replace('pm 1', '$\\pm 1$')
    
    with open(output_path, 'w', encoding='utf-8') as f:
        f.write(content)
    
    # Count remaining English
    lines = content.split('\n')
    total_lines = len(lines)
    
    print(f"Traducción completada: {output_path}")
    print(f"Total de líneas: {total_lines}")


